1226	func (r *OpenCodeHookRunner) runOpenCodeHookInRepoDir(hookName string, inputJSON []byte) error {
1227		// Command structure: entire hooks opencode <hook-name>
1228		cmd := exec.Command(getTestBinary(), "hooks", "opencode", hookName)
1229		cmd.Dir = r.RepoDir
1230		cmd.Stdin = bytes.NewReader(inputJSON)
1231		cmd.Env = append(testutil.GitIsolatedEnv(),
1232			"ENTIRE_TEST_OPENCODE_PROJECT_DIR="+r.OpenCodeProjectDir,
1233			"ENTIRE_TEST_OPENCODE_MOCK_EXPORT=1", // Use pre-written mock transcript instead of calling opencode export
1234		)
1235	
1236		output, err := cmd.CombinedOutput()
1237		if err != nil {
1238			return fmt.Errorf("hook %s failed: %w\nInput: %s\nOutput: %s",
1239				hookName, err, inputJSON, output)
1240		}
1241	
1242		r.T.Logf("OpenCode hook %s output: %s", hookName, output)
1243		return nil
1244	}
